import type { RequestHandler } from "@qwik.dev/router";

/** Preserve old bookmarks while keeping version history inside the editor. */
export const onGet: RequestHandler = ({ redirect }) => {
  throw redirect(302, "/editor/?panel=history");
};
import {
  component$,
  useStore,
  useStylesScoped$,
  useVisibleTask$,
} from "@qwik.dev/core";
import { Link, type DocumentHead } from "@qwik.dev/router";
import type { RubricResult } from "../../types";
import {
  loadActiveFolioIdFromIdb,
  loadRubricResultFromIdb,
} from "../../utils/idb";
import { renderMarkdown } from "../../utils/markdown";
import { GradeStamp } from "../../components/rubric/grade-stamp";

interface RubricPageStore {
  result: RubricResult | null;
  loaded: boolean;
}

const GRADE_COLOR: Record<string, string> = {
  "A+": "var(--color-accent-green)",
  A: "var(--color-accent-green)",
  "A-": "var(--color-accent-green)",
  "B+": "var(--color-accent-blue)",
  B: "var(--color-accent-blue)",
  "B-": "var(--color-accent-blue)",
  "C+": "var(--color-accent-amber)",
  C: "var(--color-accent-amber)",
  "C-": "var(--color-accent-amber)",
  "D+": "var(--color-vermilion)",
  D: "var(--color-vermilion)",
  "D-": "var(--color-vermilion)",
  F: "var(--color-vermilion)",
};

function scoreColor(score: number, max: number): string {
  const pct = score / max;
  if (pct >= 0.8) return "var(--color-accent-green)";
  if (pct >= 0.6) return "var(--color-accent-amber)";
  return "var(--color-accent-red)";
}

function pct(n: number): number {
  return Math.round(n * 100);
}

/** Concrete, prescriptive next step for a low-scoring criterion. */
function nextMoveFor(id: string): string {
  const moves: Record<string, string> = {
    thesis:
      "State the load-bearing claim in one sentence near the top, then make every section earn it.",
    evidence:
      "Pick the two weakest claims and attach a source, example, or number to each.",
    structure:
      "Add a section break or transition where the argument changes gears; cut a paragraph that repeats.",
    pacing:
      "Vary sentence length — break one long sentence in three, and merge two short ones.",
    voice:
      "Rewrite the opening line in the target tone; let it set the register for the rest.",
    vocabulary:
      "Replace three abstractions with concrete nouns; cut one piece of jargon per paragraph.",
    paragraph: "Split any paragraph over ~6 sentences; give each a single job.",
    engagement:
      "Put a stake or a question in the first 100 words so the reader knows why to continue.",
  };
  return (
    moves[id] ??
    "Make the one change that would most move this score, then re-read."
  );
}

/** Static curve anchors for "the brutal curve" explainer. */
const CURVE_ANCHORS: Array<[number, number, string]> = [
  [
    50,
    50,
    "A C-grade draft stays a C. It may have a promising idea, but it is not ready to carry the reader yet.",
  ],
  [
    60,
    58,
    "A coherent draft with a clear point, still needing substantial revision before publication.",
  ],
  [
    70,
    67,
    "A strong first pass: an engaging class essay, blog post, or early magazine draft with room to sharpen.",
  ],
  [
    80,
    76,
    "A polished, publishable-feeling essay or reported feature, with a few visible limits keeping it from the top tier.",
  ],
  [
    90,
    86,
    "A prize-caliber essay, reported feature, or literary piece may fit here, possibly Pulitzer-level if that is what the draft is aiming to be and the execution earns it.",
  ],
  [
    95,
    93,
    "Rare, field-leading work: the kind of piece an editor would build a cover, issue, or shortlist around.",
  ],
  [
    100,
    100,
    "A virtually unimprovable draft for its purpose, audience, and form.",
  ],
];

export default component$(() => {
  const store = useStore<RubricPageStore>({ result: null, loaded: false });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(async () => {
    const folioId = await loadActiveFolioIdFromIdb();
    const cached = await loadRubricResultFromIdb(folioId);
    if (cached) store.result = cached;
    store.loaded = true;
  });

  useStylesScoped$(`
    .card {
      border: 1px solid var(--color-paper-3);
      background-color: var(--color-paper);
      background-image: url("/assets/rubric-proof-fibers.png");
      background-size: 24rem 24rem;
      border-radius: 4px;
    }
    .bar {
      height: 4px;
      background: var(--color-paper-2);
      border-radius: 2px;
      overflow: hidden;
    }
    .bar > span {
      display: block;
      height: 100%;
    }
    .anchor {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 1rem;
      padding: 0.65rem 0.85rem;
      border-bottom: 1px dashed var(--color-paper-3);
    }
    .anchor:last-child { border-bottom: none; }
  `);

  return (
    <div
      class="min-h-screen bg-[var(--color-paper-soft)] text-[var(--color-ink)]"
      style={{ fontFamily: "var(--font-serif)" }}
    >
      <div class="max-w-5xl mx-auto px-6 py-8">
        <div class="flex items-center justify-between mb-6">
          <div>
            <p
              class="dept-label mb-1"
              style={{ fontFamily: "var(--font-typewriter)" }}
            >
              Twyne
            </p>
            <h1
              style={{
                fontFamily: "var(--font-display)",
                fontWeight: 700,
                fontSize: "1.75rem",
                color: "var(--color-ink)",
              }}
            >
              The Galley Proof
            </h1>
            <p class="text-sm text-[var(--color-ink-light)] mt-1">
              The full breakdown — what the judges said, what the rubric
              counted, what to fix next.
            </p>
          </div>
          <Link
            href="/editor"
            class="btn-paper text-sm"
            style={{ fontFamily: "var(--font-display)" }}
          >
            ← Back to desk
          </Link>
        </div>

        {!store.loaded && (
          <p class="text-sm text-[var(--color-ink-muted)]">Loading…</p>
        )}

        {store.loaded && !store.result && (
          <div class="card p-8 text-center">
            <p
              class="text-4xl"
              style={{
                fontFamily: "var(--font-display)",
                color: "var(--color-cobalt)",
              }}
            >
              ❧
            </p>
            <p class="mt-3 text-sm text-[var(--color-ink-light)] max-w-md mx-auto">
              No galley on file yet. Open the proof desk in the right panel and
              run
              <em> Send to copyedit</em> to start.
            </p>
            <Link href="/editor" class="btn-press mt-4 inline-block text-sm">
              ← Back to desk
            </Link>
          </div>
        )}

        {store.result && (
          <div class="space-y-6">
            {/* Overall */}
            <section class="card p-6">
              <div class="flex items-stretch gap-6">
                <GradeStamp
                  grade={store.result.overallGrade}
                  score={store.result.overallScore}
                  color={
                    GRADE_COLOR[store.result.overallGrade] ?? "var(--color-ink)"
                  }
                  size="report"
                  animated
                />
                <div class="flex-1 min-w-0">
                  <p class="dept-label">Editor's Mark</p>
                  <p
                    class="mt-0.5 text-2xl text-[var(--color-ink)]"
                    style={{
                      fontFamily: "var(--font-display)",
                      fontWeight: 600,
                    }}
                  >
                    {store.result.overallScore}
                    <span class="text-sm text-[var(--color-ink-muted)]">
                      {" "}
                      / 100
                    </span>
                  </p>
                  <p
                    class="mt-2 text-sm leading-6 text-[var(--color-ink-light)]"
                    style={{ fontFamily: "var(--font-serif)" }}
                  >
                    {store.result.summary}
                  </p>
                  <p
                    class="mt-3 text-[0.65rem] text-[var(--color-ink-muted)]"
                    style={{
                      fontFamily: "var(--font-typewriter)",
                      letterSpacing: "0.1em",
                    }}
                  >
                    {new Date(store.result.timestamp).toLocaleString()}
                  </p>
                </div>
              </div>
            </section>

            {/* The brutal curve */}
            <section class="card p-6">
              <p class="dept-label">The Brutal Curve</p>
              <h2
                class="mt-0.5 text-lg text-[var(--color-ink)]"
                style={{ fontFamily: "var(--font-display)", fontWeight: 600 }}
              >
                Why a "good" draft is still a C
              </h2>
              <p
                class="mt-2 text-xs leading-5 text-[var(--color-ink-light)]"
                style={{ fontFamily: "var(--font-serif)" }}
              >
                The raw score is a blend, not a plain average: the judges' mean
                opinion counts for 45%, but the single harshest judge's score
                also counts on its own for 35% — so one editor who really isn't
                convinced can drag the grade down even if the rest of the room
                liked it. Mechanical polish (structure, pacing, citations) is
                the remaining 20%, deliberately a minor share, since clean prose
                around a hollow argument shouldn't read as a good draft. That
                raw blend is then curved: Twyne compresses the middle of the
                scale and stretches the top, so a 90+ is reserved for genuinely
                excellent work.
              </p>
              <div class="mt-4">
                {CURVE_ANCHORS.map(([raw, final, note]) => (
                  <div key={raw} class="anchor">
                    <div>
                      <span
                        class="font-mono text-sm"
                        style={{ color: "var(--color-ink-muted)" }}
                      >
                        raw {raw}
                      </span>
                      <span
                        class="ml-2 text-[0.7rem] text-[var(--color-ink-muted)]"
                        style={{
                          fontFamily: "var(--font-typewriter)",
                          letterSpacing: "0.1em",
                        }}
                      >
                        → final {final}
                      </span>
                    </div>
                    <p
                      class="text-xs text-[var(--color-ink-light)]"
                      style={{ fontFamily: "var(--font-serif)" }}
                    >
                      {note}
                    </p>
                  </div>
                ))}
              </div>
            </section>

            {/* Full narrative review */}
            {store.result.review && (
              <section class="card p-6">
                <p class="dept-label">The Critic's Full Review</p>
                <div
                  class="comment-markdown mt-3 text-[15px] leading-7 text-[var(--color-ink)]"
                  style={{ fontFamily: "var(--font-serif)" }}
                  dangerouslySetInnerHTML={renderMarkdown(store.result.review)}
                />
              </section>
            )}

            {/* Per-persona judges */}
            {store.result.judges && store.result.judges.length > 0 && (
              <section class="card p-6">
                <p class="dept-label">The Judges' Verdict</p>
                <h2
                  class="mt-0.5 text-lg text-[var(--color-ink)]"
                  style={{ fontFamily: "var(--font-display)", fontWeight: 600 }}
                >
                  Persona-by-persona
                </h2>
                <ul class="mt-3 space-y-2.5">
                  {store.result.judges.map((j) => (
                    <li
                      key={j.personaId}
                      class="flex items-start gap-3 border-b border-dashed border-[var(--color-paper-3)] pb-2.5 last:border-b-0 last:pb-0"
                    >
                      <span
                        class="font-mono text-base flex-shrink-0 w-8 text-right"
                        style={{
                          color: scoreColor(j.score, 10),
                          fontWeight: 700,
                        }}
                      >
                        {j.score}
                      </span>
                      <div class="flex-1">
                        <p
                          class="text-sm text-[var(--color-ink)]"
                          style={{
                            fontFamily: "var(--font-display)",
                            fontWeight: 600,
                          }}
                        >
                          {j.personaId}
                        </p>
                        <p
                          class="text-xs text-[var(--color-ink-light)] mt-0.5"
                          style={{ fontFamily: "var(--font-serif)" }}
                        >
                          {j.rationale}
                        </p>
                        <p
                          class="mt-0.5 text-[0.6rem] text-[var(--color-ink-muted)]"
                          style={{
                            fontFamily: "var(--font-typewriter)",
                            letterSpacing: "0.1em",
                          }}
                        >
                          provider: {j.provider}
                        </p>
                      </div>
                    </li>
                  ))}
                </ul>
              </section>
            )}

            {/* Per-criterion breakdown */}
            <section class="card p-6">
              <p class="dept-label">The Criteria</p>
              <h2
                class="mt-0.5 text-lg text-[var(--color-ink)]"
                style={{ fontFamily: "var(--font-display)", fontWeight: 600 }}
              >
                What the rubric counts
              </h2>
              <div class="mt-4 space-y-4">
                {store.result.criteria.map((c, idx) => {
                  const ratio = c.score / c.maxScore;
                  const widthPct = pct(ratio);
                  const color = scoreColor(c.score, c.maxScore);
                  return (
                    <div
                      key={c.id}
                      class="border-b border-dashed border-[var(--color-paper-3)] pb-4 last:border-b-0 last:pb-0"
                    >
                      <div class="flex items-baseline justify-between gap-3 mb-1.5">
                        <div class="flex items-baseline gap-2 min-w-0">
                          <span
                            class="text-[0.7rem] flex-shrink-0"
                            style={{
                              fontFamily: "var(--font-typewriter)",
                              color: "var(--color-ink-muted)",
                              letterSpacing: "0.15em",
                            }}
                          >
                            §{idx + 1}
                          </span>
                          <span
                            class="text-sm text-[var(--color-ink)]"
                            style={{
                              fontFamily: "var(--font-display)",
                              fontWeight: 600,
                            }}
                          >
                            {c.label}
                          </span>
                        </div>
                        <span
                          class="text-xs flex-shrink-0 font-mono"
                          style={{ color, letterSpacing: "0.1em" }}
                        >
                          {c.score}/{c.maxScore} · {widthPct}%
                        </span>
                      </div>
                      <div class="bar mb-2" role="meter" aria-label={c.label}>
                        <span
                          style={{
                            width: `${widthPct}%`,
                            backgroundColor: color,
                          }}
                        />
                      </div>
                      <p
                        class="text-xs leading-5 text-[var(--color-ink-light)]"
                        style={{ fontFamily: "var(--font-serif)" }}
                      >
                        {c.feedback}
                      </p>
                      {ratio < 0.6 && (
                        <p
                          class="mt-1.5 text-[11px] leading-5"
                          style={{
                            fontFamily: "var(--font-typewriter)",
                            color: "var(--color-vermilion)",
                          }}
                        >
                          Next move → {nextMoveFor(c.id)}
                        </p>
                      )}
                    </div>
                  );
                })}
              </div>
            </section>

            {/* Static features */}
            {store.result.staticScore && (
              <section class="card p-6">
                <p class="dept-label">Static Features</p>
                <h2
                  class="mt-0.5 text-lg text-[var(--color-ink)]"
                  style={{ fontFamily: "var(--font-display)", fontWeight: 600 }}
                >
                  What the rubric counted
                </h2>
                <div class="mt-4 grid grid-cols-2 md:grid-cols-3 gap-3 text-xs">
                  {(
                    [
                      ["length", "Length"],
                      ["structure", "Structure"],
                      ["pacing", "Pacing"],
                      ["evidence", "Evidence"],
                      ["vocabulary", "Vocabulary"],
                      ["paragraphShape", "Paragraph shape"],
                    ] as const
                  ).map(([key, label]) => {
                    const v = store.result!.staticScore!.perFeature[key];
                    return (
                      <div
                        key={key}
                        class="border border-[var(--color-paper-3)] p-3"
                        style={{
                          borderRadius: "2px",
                          background: "var(--color-paper-2)",
                        }}
                      >
                        <p
                          class="text-[0.6rem] text-[var(--color-ink-muted)]"
                          style={{
                            fontFamily: "var(--font-typewriter)",
                            letterSpacing: "0.1em",
                          }}
                        >
                          {label}
                        </p>
                        <p
                          class="mt-1 text-base font-mono"
                          style={{ color: scoreColor(v, 10) }}
                        >
                          {v.toFixed(1)}/10
                        </p>
                      </div>
                    );
                  })}
                </div>
                <p
                  class="mt-3 text-xs text-[var(--color-ink-light)]"
                  style={{
                    fontFamily: "var(--font-typewriter)",
                    letterSpacing: "0.1em",
                  }}
                >
                  {store.result.staticScore.features.wordCount.toLocaleString()}{" "}
                  words · {store.result.staticScore.features.paragraphCount}{" "}
                  paragraphs · {store.result.staticScore.features.sentenceCount}{" "}
                  sentences · {store.result.staticScore.features.citationCount}{" "}
                  citations
                </p>
                {store.result.staticScore.feedback.length > 0 && (
                  <ul
                    class="mt-3 space-y-1 text-xs text-[var(--color-ink-light)]"
                    style={{
                      fontFamily: "var(--font-serif)",
                      listStyle: "disc",
                      paddingLeft: "1.25rem",
                    }}
                  >
                    {store.result.staticScore.feedback.map((line, i) => (
                      <li key={i}>{line}</li>
                    ))}
                  </ul>
                )}
              </section>
            )}
          </div>
        )}
      </div>
    </div>
  );
});

export const head: DocumentHead = {
  title: "The Galley Proof · Twyne",
  meta: [
    {
      name: "description",
      content:
        "The full Twyne rubric: per-criterion scores, judge verdicts, and the brutal curve.",
    },
  ],
};
import { $, component$, useStore, useVisibleTask$ } from "@qwik.dev/core";
import { readActiveFolioHtml } from "../../utils/folio-export";
import {
  compareRevisionPassages,
  compareRevisions,
  createRevisionSnapshot,
  loadRevisionHistory,
  loadRevisionTasks,
  setRevisionTaskStatus,
  type RevisionSnapshot,
  type RevisionTask,
} from "../../utils/revision-history";
import { saveFolioContentToIdb } from "../../utils/idb";
import { markDirty } from "../../utils/convex-sync";

interface VersionHistoryPanelProps {
  activeFolioId: string;
  folioName: string;
}

interface VersionHistoryStore {
  loading: boolean;
  currentHtml: string;
  revisions: RevisionSnapshot[];
  tasks: RevisionTask[];
  selectedId: string | null;
  compareId: "current" | string;
  confirmRestore: boolean;
  message: string | null;
}

function checkpointLabel(revision: RevisionSnapshot): string {
  return `${revision.label} · ${new Date(revision.createdAt).toLocaleString()}`;
}

export const VersionHistoryPanel = component$<VersionHistoryPanelProps>(
  ({ activeFolioId, folioName }) => {
    const store = useStore<VersionHistoryStore>({
      loading: true,
      currentHtml: "",
      revisions: [],
      tasks: [],
      selectedId: null,
      compareId: "current",
      confirmRestore: false,
      message: null,
    });

    const refresh = $(async () => {
      store.loading = true;
      const [currentHtml, revisions, tasks] = await Promise.all([
        readActiveFolioHtml(activeFolioId),
        loadRevisionHistory(activeFolioId),
        loadRevisionTasks(activeFolioId),
      ]);
      store.currentHtml = currentHtml;
      store.revisions = revisions;
      store.tasks = tasks;
      if (!revisions.some((revision) => revision.id === store.selectedId)) {
        store.selectedId = revisions[0]?.id ?? null;
      }
      if (
        store.compareId !== "current" &&
        !revisions.some((revision) => revision.id === store.compareId)
      ) {
        store.compareId = "current";
      }
      store.loading = false;
    });

    // eslint-disable-next-line qwik/no-use-visible-task
    useVisibleTask$(({ cleanup }) => {
      void refresh();
      const onOpen = () => void refresh();
      window.addEventListener("twyne:version-history-opened", onOpen);
      cleanup(() =>
        window.removeEventListener("twyne:version-history-opened", onOpen),
      );
    });

    const saveCheckpoint = $(async () => {
      const html = await readActiveFolioHtml(activeFolioId);
      const snapshot = await createRevisionSnapshot({
        folioId: activeFolioId,
        html,
        label: "Manual checkpoint",
        source: "manual",
      });
      store.message = snapshot
        ? "Checkpoint saved."
        : "The current manuscript already has a checkpoint.";
      store.currentHtml = html;
      store.revisions = await loadRevisionHistory(activeFolioId);
      store.selectedId = store.revisions[0]?.id ?? null;
      store.compareId = "current";
    });

    const restoreSelected = $(async () => {
      const selected = store.revisions.find(
        (revision) => revision.id === store.selectedId,
      );
      if (!selected) return;
      const currentHtml = await readActiveFolioHtml(activeFolioId);
      await createRevisionSnapshot({
        folioId: activeFolioId,
        html: currentHtml,
        label: "Before restoring an earlier version",
        source: "manual",
        force: true,
      });
      await saveFolioContentToIdb(activeFolioId, selected.html);
      markDirty(["folioContent"]);
      window.dispatchEvent(
        new CustomEvent("twyne:load-folio", { detail: selected.html }),
      );
      store.currentHtml = selected.html;
      store.revisions = await loadRevisionHistory(activeFolioId);
      store.compareId = "current";
      store.confirmRestore = false;
      store.message = `Restored “${selected.label}”. Your previous draft was saved as a checkpoint.`;
    });

    const toggleTask = $(async (taskId: string, done: boolean) => {
      store.tasks = await setRevisionTaskStatus(
        activeFolioId,
        taskId,
        done ? "done" : "open",
      );
    });

    const selected = store.revisions.find(
      (revision) => revision.id === store.selectedId,
    );
    const compared =
      store.compareId === "current"
        ? {
            html: store.currentHtml,
            label: "Current manuscript",
            createdAt: Number.POSITIVE_INFINITY,
          }
        : store.revisions.find((revision) => revision.id === store.compareId);
    const comparison =
      selected && compared
        ? compareRevisions(selected.html, compared.html)
        : null;
    const passageChanges =
      selected && compared
        ? compareRevisionPassages(selected.html, compared.html)
        : [];
    const openTaskCount = store.tasks.filter(
      (task) => task.status === "open",
    ).length;

    return (
      <section class="h-full overflow-y-auto bg-[var(--color-paper)] p-4 text-[var(--color-ink)] sm:p-5">
        <header class="border-b border-[var(--color-paper-3)] pb-4">
          <p class="dept-label">Version history</p>
          <div class="mt-1 flex flex-wrap items-start justify-between gap-3">
            <div class="min-w-0">
              <h2 class="truncate font-display text-lg font-semibold">
                {folioName}
              </h2>
              <p class="mt-1 max-w-prose text-sm leading-5 text-[var(--color-ink-light)]">
                Review what changed, save a checkpoint, or restore an earlier
                manuscript without leaving the editor.
              </p>
            </div>
            <button
              type="button"
              class="btn-press shrink-0"
              onClick$={saveCheckpoint}
            >
              Save checkpoint
            </button>
          </div>
        </header>

        {store.message && (
          <p class="mt-4 text-sm text-[var(--color-sage)]" role="status">
            {store.message}
          </p>
        )}

        {store.loading ? (
          <p class="py-8 text-sm text-[var(--color-ink-light)]">
            Opening version history…
          </p>
        ) : store.revisions.length === 0 ? (
          <div class="py-10 text-center">
            <h3 class="font-display text-lg">No checkpoints yet</h3>
            <p class="mx-auto mt-2 max-w-sm text-sm leading-6 text-[var(--color-ink-light)]">
              Save the current manuscript to start a history you can compare and
              restore.
            </p>
          </div>
        ) : (
          <>
            <div class="mt-5 grid gap-3 sm:grid-cols-2">
              <label class="text-xs font-semibold text-[var(--color-ink-light)]">
                Earlier checkpoint
                <select
                  class="mt-1 block w-full border border-[var(--color-paper-3)] bg-[var(--color-paper)] px-3 py-2 text-sm text-[var(--color-ink)] focus-ring"
                  value={store.selectedId ?? ""}
                  onChange$={(_, element) => {
                    store.selectedId = element.value || null;
                    if (store.compareId === store.selectedId) {
                      store.compareId = "current";
                    }
                    store.confirmRestore = false;
                  }}
                >
                  {store.revisions.map((revision) => (
                    <option key={revision.id} value={revision.id}>
                      {checkpointLabel(revision)}
                    </option>
                  ))}
                </select>
              </label>
              <label class="text-xs font-semibold text-[var(--color-ink-light)]">
                Compare with
                <select
                  class="mt-1 block w-full border border-[var(--color-paper-3)] bg-[var(--color-paper)] px-3 py-2 text-sm text-[var(--color-ink)] focus-ring"
                  value={store.compareId}
                  onChange$={(_, element) => {
                    store.compareId = element.value;
                  }}
                >
                  <option value="current">Current manuscript</option>
                  {store.revisions
                    .filter((revision) => revision.id !== store.selectedId)
                    .map((revision) => (
                      <option key={revision.id} value={revision.id}>
                        {checkpointLabel(revision)}
                      </option>
                    ))}
                </select>
              </label>
            </div>

            {comparison && (
              <div class="mt-4 flex flex-wrap gap-x-5 gap-y-2 border-y border-[var(--color-paper-3)] py-3 text-xs text-[var(--color-ink-light)]">
                <span>
                  <strong class="text-[var(--color-ink)]">
                    {comparison.wordsChanged}
                  </strong>{" "}
                  words changed
                </span>
                <span>
                  {comparison.wordsBefore} → {comparison.wordsAfter} words
                </span>
                <span>
                  {comparison.paragraphsBefore} → {comparison.paragraphsAfter}{" "}
                  passages
                </span>
              </div>
            )}

            <section class="mt-5" aria-labelledby="changed-passages-heading">
              <div class="flex flex-wrap items-center justify-between gap-3">
                <div>
                  <h3
                    id="changed-passages-heading"
                    class="font-display text-base font-semibold"
                  >
                    Changed passages
                  </h3>
                  {selected && compared && (
                    <p class="mt-1 text-xs text-[var(--color-ink-light)]">
                      {selected.label} compared with {compared.label}
                    </p>
                  )}
                </div>
                {selected && (
                  <button
                    type="button"
                    class="btn-paper"
                    onClick$={() => {
                      store.confirmRestore = true;
                    }}
                  >
                    Restore checkpoint
                  </button>
                )}
              </div>

              {passageChanges.length === 0 ? (
                <p class="mt-4 bg-[var(--color-paper-soft)] p-4 text-sm text-[var(--color-ink-light)]">
                  These versions have the same manuscript text.
                </p>
              ) : (
                <ol class="mt-4 space-y-3">
                  {passageChanges.map((change, index) => (
                    <li
                      key={`${index}-${change.before ?? "added"}`}
                      class="border border-[var(--color-paper-3)] bg-[var(--color-paper-soft)] p-3"
                    >
                      {change.before && (
                        <div class="bg-[color-mix(in_srgb,var(--color-vermilion)_7%,var(--color-paper))] p-3">
                          <p class="text-[10px] font-semibold uppercase tracking-[0.1em] text-[var(--color-vermilion)]">
                            Removed
                          </p>
                          <p class="mt-1 whitespace-pre-wrap font-serif text-sm leading-6">
                            {change.before}
                          </p>
                        </div>
                      )}
                      {change.after && (
                        <div
                          class={[
                            "bg-[color-mix(in_srgb,var(--color-sage)_9%,var(--color-paper))] p-3",
                            { "mt-2": Boolean(change.before) },
                          ]}
                        >
                          <p class="text-[10px] font-semibold uppercase tracking-[0.1em] text-[var(--color-sage)]">
                            Added
                          </p>
                          <p class="mt-1 whitespace-pre-wrap font-serif text-sm leading-6">
                            {change.after}
                          </p>
                        </div>
                      )}
                    </li>
                  ))}
                </ol>
              )}
            </section>

            {store.confirmRestore && selected && (
              <div class="mt-5 border border-[var(--color-vermilion)] bg-[var(--color-paper-soft)] p-4">
                <p class="text-sm leading-6">
                  Twyne will save the current manuscript first, then restore “
                  {selected.label}”.
                </p>
                <div class="mt-3 flex flex-wrap gap-2">
                  <button
                    type="button"
                    class="btn-press"
                    onClick$={restoreSelected}
                  >
                    Save current and restore
                  </button>
                  <button
                    type="button"
                    class="btn-paper"
                    onClick$={() => {
                      store.confirmRestore = false;
                    }}
                  >
                    Keep current manuscript
                  </button>
                </div>
              </div>
            )}

            {store.tasks.length > 0 && (
              <details class="mt-5 border-t border-[var(--color-paper-3)] pt-4">
                <summary class="cursor-pointer text-sm font-semibold focus-ring">
                  Revision tasks ({openTaskCount} open)
                </summary>
                <div class="mt-3 space-y-2">
                  {store.tasks.map((task) => (
                    <label
                      key={task.id}
                      class="flex cursor-pointer gap-3 bg-[var(--color-paper-soft)] p-3"
                    >
                      <input
                        type="checkbox"
                        class="mt-1"
                        checked={task.status === "done"}
                        onChange$={(_, element) =>
                          toggleTask(task.id, element.checked)
                        }
                      />
                      <span
                        class={[
                          "text-sm leading-5",
                          {
                            "text-[var(--color-ink-light)] line-through":
                              task.status === "done",
                          },
                        ]}
                      >
                        {task.title}
                      </span>
                    </label>
                  ))}
                </div>
              </details>
            )}
          </>
        )}
      </section>
    );
  },
);

