    await saveMetaToIdb(`rubric-criteria:${folioId}`, criteria);
  }
  if (Array.isArray(history) && history.length > 0) {
    await saveMetaToIdb(
      `rubric-history:${folioId}`,
      history.map((entry) => ({ ...entry, folioId })),
    );
  }

