 * Attach pre-folio editorial artifacts to exactly one existing folio.
 *
 * This runs once, before a writer creates or switches to another folio. It
 * intentionally moves rather than copies the old singleton records so a new
 * folio can never inherit the previous room by falling back to legacy paths.
 */
export async function migrateLegacyEditorialArtifacts(
  folioId: string,
  claimLegacy: boolean,
): Promise<void> {
  // With multiple possible owners, preserve old unscoped data without showing
  // it in any folio. A later recovery can ask where it belongs.
  if (!folioId || !claimLegacy) return;
  const migrated = await loadMetaFromIdb<string>(MIGRATION_KEY);
  if (migrated) return;

  await Promise.all([
    moveLegacyArray<PersonaFeedback>(
      folioId,
      "/persona-notes.json",
      "persona-notes.json",
    ),
    moveLegacyArray<PersonaReply>(
      folioId,
      "/persona-replies.json",
      "persona-replies.json",
    ),
    moveLegacyArray<Suggestion>(
      folioId,
      "/suggestions.json",
      "suggestions.json",
    ),
  ]);

  const [
    legacyRubric,
    legacyLixRubric,
    legacyAnalysis,
    criteria,
    history,
  ] = await Promise.all([
    loadRubricResultFromIdb(),
    readFileAsJson<RubricResult>("/rubric-result.json"),
    loadRoomAnalysisFromIdb(),
    loadMetaFromIdb<RubricCriterionSpec[]>("rubric-criteria"),
    loadMetaFromIdb<RubricHistoryEntry[]>("rubric-history"),
  ]);
  const rubric = legacyRubric ?? legacyLixRubric;
  if (rubric) {
    await saveRubricResultToIdb(
      { ...rubric, folioId } as RubricResult,
      folioId,
    );
    await writeFileAsJson(scopedPath(folioId, "rubric-result.json"), {
      ...rubric,
      folioId,
    });
    if (legacyLixRubric) {
      await writeFileAsJson("/rubric-result.json", null);
    }
  }
  if (legacyAnalysis) {
    await saveRoomAnalysisToIdb(
      { ...legacyAnalysis, folioId } as RoomAnalysis,
      folioId,
    );
  }
  if (Array.isArray(criteria) && criteria.length > 0) {
    await saveMetaToIdb(`rubric-criteria:${folioId}`, criteria);
  }
  if (Array.isArray(history) && history.length > 0) {
    await saveMetaToIdb(
      `rubric-history:${folioId}`,
      history.map((entry) => ({ ...entry, folioId })),
    );
  }

  const comments =
    (await readFileAsJson<Array<{ folioId?: string }>>(
      "/user-comments.json",
    )) ?? [];
  if (comments.length > 0) {
    await writeFileAsJson(
      "/user-comments.json",
      comments.map((comment) =>
        comment.folioId ? comment : { ...comment, folioId },
      ),
    );
  }

  const bibliography =
    (await readFileAsJson<BibEntry[]>("/bibliography.json")) ?? [];
  if (bibliography.length > 0) {
    await writeFileAsJson(
      "/bibliography.json",
      bibliography.map((entry) =>
        entry.folioId ? entry : { ...entry, folioId },
      ),
    );
  }

  await saveMetaToIdb(MIGRATION_KEY, folioId);
}
import {
  component$,
  isDev,
  createContextId,
  Slot,
  useContext,
  useContextProvider,
  useSignal,
  useVisibleTask$,
  noSerialize,
  type NoSerialize,
  type Signal,
} from "@qwik.dev/core";
import { ConvexClient, type ConvexClientOptions } from "convex/browser";
import { capturePostHogEvent } from "./posthog-context";
import {
  normalizeApplicationError,
  sanitizeErrorMetadata,
} from "./application-errors";

const ConvexClientContext = createContextId<
  Signal<NoSerialize<ConvexClient> | null>
>("twyne.convex-client");

interface ConvexProviderProps {
  client?: ConvexClient;
  options?: ConvexClientOptions;
  url?: string;
}

export function useConvexClient() {
  return useContext(ConvexClientContext);
}

type ConvexLogger = NonNullable<
  Exclude<ConvexClientOptions["logger"], boolean>
>;

export function createProductionConvexLogger(): ConvexLogger {
  const capture = (level: "warn" | "error", args: unknown[]) => {
    const error = normalizeApplicationError(args[args.length - 1], {
      source: "convex",
    });
    void capturePostHogEvent("$exception", {
      distinct_id: "convex-browser",
      $exception_type: "ConvexClientError",
      $exception_message: error.message,
      $exception_is_unhandled: false,
      $level: level,
      twyne_error_code: error.code,
      twyne_error_reference_id: error.referenceId,
      twyne_error_source: error.source,
      ...sanitizeErrorMetadata({ operation: "convex-client" }),
    });
  };
  return {
    logVerbose() {},
    log() {},
    warn(...args: unknown[]) {
      capture("warn", args);
    },
    error(...args: unknown[]) {
      capture("error", args);
    },
  };
}

export const ConvexProvider = component$(
  ({ client, options, url }: ConvexProviderProps) => {
    const clientSignal = useSignal<NoSerialize<ConvexClient> | null>(
      client ? noSerialize(client) : null,
    );

    useContextProvider(ConvexClientContext, clientSignal);

    // Keep the client creation on the client side so SSR never evaluates browser state.
    // eslint-disable-next-line qwik/no-use-visible-task
    useVisibleTask$(
      ({ cleanup, track }) => {
        const trackedUrl = track(() => url);

        if (clientSignal.value || !trackedUrl) {
          return;
        }

        const createdClient = new ConvexClient(trackedUrl, {
          ...options,
          logger:
            options?.logger ?? (isDev ? true : createProductionConvexLogger()),
          verbose: options?.verbose ?? false,
          reportDebugInfoToConvex: options?.reportDebugInfoToConvex ?? false,
        });
        clientSignal.value = noSerialize(createdClient);

        cleanup(() => {
          if (clientSignal.value === createdClient) {
            clientSignal.value = null;
          }

          void createdClient.close();
        });
      },
      { strategy: "document-ready" },
    );

    return <Slot />;
  },
);
"}
