import { loadMetaFromIdb, saveMetaToIdb } from "./idb";

export interface SavedWritingPassage { id: string; text: string }
export interface SavedResearchPair {
  id: string;
  claim: string;
  source: string;
  previousClaim?: string;
}
export interface WritingToolsNotebook {
  audience: string;
  voiceSamples: SavedWritingPassage[];
  scraps: SavedWritingPassage[];
  sources: SavedResearchPair[];
  intentionalPromises: string[];
}

let storage = { load: loadMetaFromIdb, save: saveMetaToIdb };
export function __setWritingToolsStorageForTests(adapter: typeof storage | null) {
  storage = adapter ?? { load: loadMetaFromIdb, save: saveMetaToIdb };
}

export function emptyWritingToolsNotebook(): WritingToolsNotebook {
  return { audience: "", voiceSamples: [], scraps: [], sources: [], intentionalPromises: [] };
}

function passages(value: unknown): SavedWritingPassage[] {
  if (!Array.isArray(value)) return [];
  return value.filter((item) => item && typeof item.id === "string" && typeof item.text === "string");
}

export async function loadWritingToolsNotebook(folioId: string): Promise<WritingToolsNotebook> {
  if (!folioId) return emptyWritingToolsNotebook();
  const value = await storage.load<Partial<WritingToolsNotebook>>(`writing-tools:${folioId}`);
  if (!value || typeof value !== "object") return emptyWritingToolsNotebook();
  return {
    audience: typeof value.audience === "string" ? value.audience : "",
    voiceSamples: passages(value.voiceSamples),
    scraps: passages(value.scraps),
    sources: Array.isArray(value.sources) ? value.sources.filter((item) => item && typeof item.id === "string" && typeof item.claim === "string" && typeof item.source === "string" && (item.previousClaim === undefined || typeof item.previousClaim === "string")) : [],
    intentionalPromises: Array.isArray(value.intentionalPromises) ? value.intentionalPromises.filter((id) => typeof id === "string") : [],
  };
}

/** Verify the write: the shared IDB helper deliberately absorbs storage failures. */
export async function saveWritingToolsNotebook(folioId: string, notebook: WritingToolsNotebook): Promise<void> {
  if (!folioId) throw new Error("No folio selected");
  const snapshot = JSON.parse(JSON.stringify(notebook)) as WritingToolsNotebook;
  await storage.save(`writing-tools:${folioId}`, snapshot);
  const saved = await loadWritingToolsNotebook(folioId);
  if (JSON.stringify(saved) !== JSON.stringify(snapshot)) throw new Error("Local save failed");
}

import { afterEach, describe, expect, test } from "bun:test";
import { __setWritingToolsStorageForTests, emptyWritingToolsNotebook, loadWritingToolsNotebook, saveWritingToolsNotebook } from "./writing-tools-storage";

afterEach(() => __setWritingToolsStorageForTests(null));

describe("writing tools notebook", () => {
  test("isolates saved passages, source pairs and promise decisions by folio", async () => {
    const values = new Map<string, unknown>();
    __setWritingToolsStorageForTests({ load: async <T>(key: string) => values.get(key) as T ?? null, save: async (key, value) => { values.set(key, value); } });
    const notebook = emptyWritingToolsNotebook();
    notebook.voiceSamples.push({ id: "voice", text: "My peculiar sentence." });
    notebook.scraps.push({ id: "scrap", text: "The cut anecdote." });
    notebook.sources.push({ id: "source", claim: "Most readers", previousClaim: "Some readers", source: "Two of six readers" });
    notebook.intentionalPromises.push("promise:abc");
    await saveWritingToolsNotebook("one", notebook);
    notebook.scraps.length = 0;
    expect((await loadWritingToolsNotebook("one")).scraps).toHaveLength(1);
    expect((await loadWritingToolsNotebook("one")).sources[0].previousClaim).toBe("Some readers");
    expect(await loadWritingToolsNotebook("two")).toEqual(emptyWritingToolsNotebook());
  });

  test("does not confirm saves when IndexedDB absorbed a failed write", async () => {
    __setWritingToolsStorageForTests({ load: async () => null, save: async () => {} });
    const notebook = emptyWritingToolsNotebook();
    notebook.audience = "A curious newcomer";
    await expect(saveWritingToolsNotebook("one", notebook)).rejects.toThrow("Local save failed");
  });

  test("ignores malformed saved fields", async () => {
    __setWritingToolsStorageForTests({ load: async <T>() => ({ voiceSamples: [null, { id: "x", text: 9 }], sources: [{ id: "s", claim: "c" }], intentionalPromises: [null, "keep"] }) as T, save: async () => {} });
    expect(await loadWritingToolsNotebook("one")).toEqual({ ...emptyWritingToolsNotebook(), intentionalPromises: ["keep"] });
  });
});

