import { $, component$, useStore, useStylesScoped$, useVisibleTask$ } from "@qwik.dev/core";
import { Link } from "@qwik.dev/router";
import { api } from "../../../convex/_generated/api";
import { useConvexClient } from "../../utils/convex-context";
import { loadActiveFolioIdFromIdb, loadBriefFromIdb, loadFolioContentFromIdb, loadFoliosFromIdb } from "../../utils/idb";
import { loadPersonaNotesLocally } from "../../utils/convex-sync";
import { loadRevisionHistory } from "../../utils/revision-history";
import { emptyWritingToolsNotebook, loadWritingToolsNotebook, saveWritingToolsNotebook, type WritingToolsNotebook } from "../../utils/writing-tools-storage";
import { WRITING_LENSES, runWritingLens, type WritingLensId, type WritingLensInput, type WritingLensResult } from "../../utils/writing-lenses";

interface ToolsState {
  loaded: boolean; folioId: string; folioName: string; draft: string;
  revisions: { id: string; text: string; label: string }[];
  notes: { id: string; text: string; author: string }[];
  notebook: WritingToolsNotebook;
  lens: WritingLensId; previousId: string; currentId: string; focus: string;
  newPassage: string; claim: string; previousClaim: string; source: string;
  busy: boolean; saving: boolean; saveNotice: string; error: string;
  result: WritingLensResult | null; resultKey: string; stale: boolean;
}

/** Runs only in the browser; retain paragraph boundaries for the reader lens. */
function manuscriptText(html: string): string {
  const document = new DOMParser().parseFromString(html, "text/html");
  document.querySelectorAll("script,style").forEach((node) => node.remove());
  document.querySelectorAll("p,h1,h2,h3,h4,h5,h6,li,blockquote,div,br").forEach((node) => node.append("\n\n"));
  return (document.body.textContent ?? "").replace(/[ \t]+/g, " ").replace(/\n\s*\n/g, "\n\n").trim();
}

function inputs(state: ToolsState): WritingLensInput {
  return {
    draft: state.currentId === "current" ? state.draft : (state.revisions.find((revision) => revision.id === state.currentId)?.text ?? ""),
    previousDraft: state.revisions.find((revision) => revision.id === state.previousId)?.text,
    audience: state.notebook.audience,
    voiceSamples: state.notebook.voiceSamples, scraps: state.notebook.scraps,
    notes: state.notes,
    revisions: [...state.revisions].reverse().map(({ id, text }) => ({ id, text })),
    sources: state.notebook.sources, intentionalPromises: state.notebook.intentionalPromises,
    focus: state.focus,
  };
}

function inputKey(state: ToolsState): string {
  return JSON.stringify([state.folioId, state.lens, inputs(state)]);
}

export const WritingTools = component$(() => {
  const client = useConvexClient();
  const state = useStore<ToolsState>({ loaded: false, folioId: "", folioName: "", draft: "", revisions: [], notes: [], notebook: emptyWritingToolsNotebook(), lens: "revision", previousId: "", currentId: "current", focus: "", newPassage: "", claim: "", previousClaim: "", source: "", busy: false, saving: false, saveNotice: "", error: "", result: null, resultKey: "", stale: false });

  const refresh = $(async () => {
    const folioId = await loadActiveFolioIdFromIdb();
    if (!folioId) { state.loaded = true; return; }
    const [html, revisions, notes, folios] = await Promise.all([loadFolioContentFromIdb(folioId), loadRevisionHistory(folioId), loadPersonaNotesLocally(folioId), loadFoliosFromIdb()]);
    if ((await loadActiveFolioIdFromIdb()) !== folioId) return;
    if (state.folioId !== folioId) {
      const [notebook, brief] = await Promise.all([loadWritingToolsNotebook(folioId), loadBriefFromIdb(folioId)]);
      state.notebook = notebook;
      if (!notebook.audience) state.notebook.audience = brief?.answers.audience ?? "";
      state.previousId = revisions.find((revision) => revision.html !== html)?.id ?? revisions[0]?.id ?? "";
      state.currentId = "current";
      state.result = null; state.resultKey = ""; state.stale = false;
      state.newPassage = ""; state.claim = ""; state.previousClaim = ""; state.source = "";
      state.focus = ""; state.saveNotice = "";
    }
    state.folioId = folioId;
    state.folioName = folios.find((folio) => folio.id === folioId)?.name ?? "Current folio";
    state.draft = manuscriptText(html);
    state.revisions = revisions.map((revision) => ({ id: revision.id, text: manuscriptText(revision.html), label: `${revision.label} · ${new Date(revision.createdAt).toLocaleString()}` }));
    state.notes = notes.map((note, index) => ({ id: note.noteId ?? `${note.personaId}:${note.timestamp}:${index}`, text: note.feedback, author: note.personaName }));
    state.loaded = true;
    if (state.result && state.resultKey !== inputKey(state)) state.stale = true;
  });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(({ cleanup }) => {
    void refresh().catch(() => { state.error = "Your folio could not be loaded. Return to the desk and try again."; state.loaded = true; });
    const onFocus = () => { void refresh().catch(() => {}); };
    window.addEventListener("focus", onFocus);
    const interval = window.setInterval(onFocus, 3000);
    cleanup(() => { window.removeEventListener("focus", onFocus); window.clearInterval(interval); });
  });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(({ track }) => {
    const key = track(() => inputKey(state));
    if (state.result && key !== state.resultKey) state.stale = true;
  });

  const save = $(async () => {
    if (state.saving) return false;
    state.saving = true; state.saveNotice = "";
    try {
      await saveWritingToolsNotebook(state.folioId, state.notebook);
      state.saveNotice = "Saved on this device.";
      return true;
    } catch {
      state.saveNotice = "Could not save on this device. Your entries are still here; try Save again.";
      return false;
    } finally { state.saving = false; }
  });

  const run = $(async () => {
    if (state.busy) return;
