    try {
      await refresh();
      if (!client.value) { state.error = "Writing tools are not connected yet. Please try again in a moment."; return; }
      const key = inputKey(state);
      const requestInput = JSON.parse(JSON.stringify(inputs(state))) as WritingLensInput;
      const result = await runWritingLens(state.lens, requestInput, async (request) => client.value!.action(api.systemOne.ask, {
        ...request,
        state: Object.fromEntries(Object.entries(request.state).map(([name, value]) => [name, typeof value === "string" ? value : JSON.stringify(value)])),
      }));
      await refresh();
      if (key !== inputKey(state)) { state.stale = true; return; }
      state.result = result; state.resultKey = key;
