    {!state.loaded ? <p role="status">Loading your folio and saved material…</p> : !state.folioId ? <div class="empty"><h2>Start with a draft</h2><p>Open a folio at your desk, then return here to explore its revisions, voice and reader experience.</p><Link href="/editor/" class="btn-press">Open the desk</Link></div> : <div class="tools-grid">
